const themeToggle=document.querySelector(".theme-toggle");themeToggle?.addEventListener("click",()=>{const e=document.body.classList.toggle("dark-mode");localStorage.setItem("horario-theme",e?"dark":"light"),themeToggle.setAttribute("aria-pressed",String(e)),document.dispatchEvent(new CustomEvent("themechange"))});const burger=document.querySelector(".nav__burger"),links=document.querySelector(".nav__links");burger?.addEventListener("click",()=>{const e=links?.classList.toggle("open");burger.setAttribute("aria-expanded",String(Boolean(e)))});const here=location.pathname.split("/").pop()||"index.html";document.querySelectorAll(".nav__link").forEach(e=>{e.getAttribute("href")===here&&e.classList.add("active")});